from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

modal_cva = cva(
    base="relative w-full rounded-lg border bg-background shadow-lg",
    variants={
        "size": {
            "sm": "max-w-sm p-4",
            "default": "max-w-lg p-6 sm:max-w-[425px]",
            "lg": "max-w-xl p-8",
        },
    },
    default_variants={
        "size": "default",
    }
)

class ModalNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        # Evaluate cva
        final_class = modal_cva(**resolved_kwargs)

        # Separate extra attributes
        known_args = ["size", "id", "title", "description", "action_label", "class", "class_name", "slot"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        # Render body
        slot = self.nodelist.render(context) if self.nodelist else ""
        id_val = resolved_kwargs.get("id", "modal")
        title = resolved_kwargs.get("title", "")
        description = resolved_kwargs.get("description", "")
        action_label = resolved_kwargs.get("action_label", "")

        t = context.template.engine.get_template('components/modal.html')
        new_context = context.new({
            "class": final_class,
            "slot": slot,
            "id": id_val,
            "title": title,
            "description": description,
            "action_label": action_label,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_modal')
def djinn_modal(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_modal',))
    parser.delete_first_token()
    return ModalNode(nodelist, kwargs)
